import pandas as pd

def status_of_flight_tickets(flights: pd.DataFrame, passengers: pd.DataFrame) -> pd.DataFrame:
    df = passengers.merge(flights, on="flight_id")
    df["rk"] = df.groupby("flight_id")["booking_time"].rank(method="min")
    df["status"] = df.apply(lambda r: "Confirmed" if r["rk"] <= r["capacity"] else "Waitlist", axis=1)
    return df[["passenger_id", "status"]].sort_values("passenger_id")
